Giả sử không bật các cờ tối ưu (như -O2 hoặc -O3 trong GCC)
```cpp
#include <iostream>
using namespace std;
template <typename T>
T maxVal(T a, T b) {
  return (a > b) ? a : b;
}
int main() {
  maxVal(3, 7);
         // (1)
      maxVal(3.5, 2.5);
                           // (2)
      maxVal<int>(5, 10);  // (3)
  maxVal(3, 7);
         // (4) lần thứ hai
}
```
